function membrane<T extends object>(target: T, policy: Policy): T {
  const wrappers = new WeakMap<object, unknown>();       // identity map
  const handler: ProxyHandler<object> = { get(t, key, r) {
    const v = Reflect.get(t, key, r) as unknown;         // forward, then wrap
    return typeof v === 'function'
      ? (...a: unknown[]) => wrap((v as Fn).apply(t, a.map(wrap))) : wrap(v);
  } };
  const wrap = (v: unknown): unknown => (v !== null && typeof v === 'object'
    ? (wrappers.get(v) ?? (wrappers.set(v, new Proxy(v as object, handler)), wrappers.get(v))) : v);
  return new Proxy(target, handler) as T;                // cast: traps outrun the types
}
